contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address u, uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance");
        require(u == address(this), "caller must be this contract");

        uint256 beforeC = address(c).balance;
        uint256 beforeU = c.getBalance(u); if (__ESBMC_reverted()) return;

        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;

        uint256 afterC = address(c).balance;
        uint256 afterU = c.getBalance(u); if (__ESBMC_reverted()) return;

        assert(afterC == beforeC + amount && afterU == beforeU + amount);
    }

    receive() external payable {}
}

