// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(address u, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        u = address(this);
        uint256 beforeC = address(c).balance;
        uint256 beforeU;
        try c.getBalance(u) returns (uint256 __r) { beforeU = __r; } catch { return; }
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 afterC = address(c).balance;
        uint256 afterU;
        try c.getBalance(u) returns (uint256 __r) { afterU = __r; } catch { return; }
        assertTrue(afterC == beforeC + amount && afterU == beforeU + amount);
    }

    function testFuzz_run(address u, uint256 amount) public {
        _run(u, amount);
    }

    receive() external payable {}
}
